-- GENERATED by scripts/export_semantic_layer.py from metrics/registry.yaml and the dbt `meta.semantic` mappings. Do not edit by hand; change the registry or the mapping and regenerate.
--
-- Unity Catalog metric views over the dbt-built `analytics` schema. Run
-- after `dbt build --target databricks`. Each YAML body below is the
-- matching <view>.metric_view.yaml file, verbatim. Each measure is named
-- after its registry id.
--
-- Query a metric view with MEASURE(), for example:
--   SELECT channel, MEASURE(net_revenue)
--   FROM workspace.analytics.order_items_metrics
--   GROUP BY ALL;

CREATE OR REPLACE VIEW workspace.analytics.order_items_metrics
WITH METRICS
LANGUAGE YAML
AS $$
# GENERATED by scripts/export_semantic_layer.py from metrics/registry.yaml and the dbt `meta.semantic` mappings. Do not edit by hand; change the registry or the mapping and regenerate.
version: 1.1
comment: Order-item grain fact table — the dbt implementation of `base_fact_sql` in metrics/registry.yaml.
  Filterable dimensions (channel, region, category) live here so registry metrics and LookML
  measures filter the same rows. Generated from metrics/registry.yaml.
source: workspace.analytics.fct_order_items
dimensions:
- name: order_date
  expr: order_date
- name: channel
  expr: channel
- name: region
  expr: region
- name: category
  expr: category
measures:
- name: net_revenue
  expr: ROUND(SUM(revenue), 2)
  comment: 'Net Revenue. Total revenue recognized across all order line items in the period.
    Gross of returns — there is no returns table in the synthetic dataset, so treat this as
    a simplified top-line figure. [registry:net_revenue; owner: analytics-team; unit: USD]'
- name: aov
  expr: ROUND(SUM(revenue) / COUNT(DISTINCT order_id), 2)
  comment: 'Average Order Value. Net revenue divided by the number of distinct orders. Computed
    at the order grain, not the line-item grain, so multi-item orders aren''t double counted.
    [registry:aov; owner: analytics-team; unit: USD]'
$$;

CREATE OR REPLACE VIEW workspace.analytics.customers_metrics
WITH METRICS
LANGUAGE YAML
AS $$
# GENERATED by scripts/export_semantic_layer.py from metrics/registry.yaml and the dbt `meta.semantic` mappings. Do not edit by hand; change the registry or the mapping and regenerate.
version: 1.1
comment: Customer grain, including customers who never ordered. Shared source of "first order",
  "last order", and 90-day revenue for every cohort metric. Generated from metrics/registry.yaml.
source: workspace.analytics.dim_customers
dimensions:
- name: acquisition_channel
  expr: acquisition_channel
- name: region
  expr: region
- name: purchase_outcome
  expr: purchase_outcome
- name: first_order_channel
  expr: first_order_channel
  comment: Channel of the customer's first order; the attribution basis for CAC.
measures:
- name: repeat_purchase_rate
  expr: ROUND(100.0 * SUM(CASE WHEN order_count >= 2 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE
    WHEN order_count > 0 THEN 1 ELSE 0 END), 0), 1)
  comment: 'Repeat Purchase Rate. Share of customers with 2+ distinct orders (matching the
    filter), out of all customers with at least one order matching the filter. In this layer
    the rate is customer-grain: slice it by customer attributes such as region. It cannot
    follow order-level channel or category filters the way the registry formula does; use
    the resolver for those. [registry:repeat_purchase_rate; owner: analytics-team; unit: percent]'
- name: ltv_90d
  expr: ROUND(AVG(revenue_first_90d), 2)
  comment: '90-Day Customer Lifetime Value. Average net revenue generated per customer within
    90 days of their first order. A simplified LTV proxy — no discounting, no margin adjustment
    — intentionally, to keep the definition auditable at a glance rather than modeling-accurate.
    A cohort metric — not filterable by dimension in this demo. [registry:ltv_90d; owner:
    analytics-team; unit: USD]'
- name: acquisition_funnel
  expr: COUNT(customer_id)
  comment: 'Acquisition Funnel by Channel. For each acquisition channel, how many customers
    ended up Never Purchased / One-Time Buyer / Repeat Buyer. A cohort metric — uses the customer''s
    original acquisition_channel (fixed at signup), not the per-order channel used elsewhere
    in the registry, and isn''t filterable by dimension for the same reason cac_by_channel
    isn''t. Group by acquisition_channel, purchase_outcome. [registry:acquisition_funnel;
    owner: growth-team; unit: count]'
- name: churn_rate_90d
  expr: ROUND(100.0 * SUM(CASE WHEN is_churned_90d THEN 1 ELSE 0 END) / NULLIF(COUNT(is_churned_90d),
    0), 1)
  comment: '90-Day Churn Rate. Share of customers whose most recent order is more than 90
    days before the dataset''s max order date, i.e. customers who have gone quiet for a full
    quarter. A snapshot definition, not a rolling one, and not filterable by dimension in
    this demo. [registry:churn_rate_90d; owner: analytics-team; unit: percent]'
$$;

CREATE OR REPLACE VIEW workspace.analytics.channel_acquisition_metrics
WITH METRICS
LANGUAGE YAML
AS $$
# GENERATED by scripts/export_semantic_layer.py from metrics/registry.yaml and the dbt `meta.semantic` mappings. Do not edit by hand; change the registry or the mapping and regenerate.
version: 1.1
comment: 'Channel grain: total marketing spend and customers whose first order came through
  the channel. The two additive inputs to CAC, aggregated separately before joining so spend
  is never fanned out. Generated from metrics/registry.yaml.'
source: workspace.analytics.channel_acquisition
dimensions:
- name: channel
  expr: channel
measures:
- name: cac_by_channel
  expr: ROUND(SUM(spend) / NULLIF(SUM(acquired_customers), 0), 2)
  comment: 'Customer Acquisition Cost by Channel. Total marketing spend on a channel divided
    by the number of distinct customers who placed a first order on that channel, over the
    full dataset window. A cohort metric — not filterable by dimension, since spend and first-order
    attribution are already channel-grained. Group by channel. [registry:cac_by_channel; owner:
    growth-team; unit: USD]'
$$;
